const isValidIndianMobile = (mobile) => /^[6-9]\d{9}$/.test(mobile);

// Resolves the human-readable name for a DMT provider entry (the objects
// in `allBank`, from settingBank()). These are Vendor documents whose
// `name` field holds internal codes like "bank1"/"bank2"/"bank3" — the
// backend's own transaction controller treats `slug` (e.g. "instantpay",
// "nifi") as the vendor's real identity, so that's preferred here over
// `name`. No extra API call needed: it's the same object already in
// `allBank`.
// Previous implementation (commented for safety / rollback):
// const getBankDisplayName = (bank) =>
//   bank?.slug ||
//   bank?.display_name ||
//   bank?.bank_display_name ||
//   bank?.label ||
//   bank?.name ||
//   "—";

const getBankDisplayName = (bank) => {
  if (!bank) return "—";
  const rawName = (bank?.name || "").toLowerCase().trim();
  const idStr = String(bank?._id || "");

  // Instantpay DMT Pipe Bifurcation mapping:
  // Bank 1 -> Airtel Payments Bank (AB) - Limit: ₹25k
  if (rawName === "bank1" || idStr === "66bca8dd5727c7563ad6e317") {
    return "Airtel";
  }
  // Bank 2 -> Jio Payments Bank (JD) - Limit: ₹25k
  if (rawName === "bank2" || idStr === "67f7b16e384bcb556dce59ea") {
    return "Jio";
  }
  // Bank 3 -> NSDL Payments Bank (ND) - Limit: ₹25k
  if (rawName === "bank3" || idStr === "694a1b2b342764296ddca9f8") {
    return "NSDL";
  }

  return (
    bank?.display_name ||
    bank?.bank_display_name ||
    bank?.label ||
    bank?.slug ||
    bank?.name ||
    "—"
  );
};

const isInstantpayBankHelper = (bank) => {
  if (!bank) return true; // Safe default
  const slug = (bank?.slug || "").toLowerCase();
  const name = (bank?.name || "").toLowerCase();
  return slug === "instantpay" || name === "bank1" || name === "bank2" || name === "bank3";
};

