// Smart filter function: ensures alphabetical order and prioritizes exact/prefix matches (same as PPI)
const filterAndSortBankOptions = (options, query) => {
  const q = (query || "").trim().toLowerCase();
  if (!q) {
    return options;
  }

  const escapedQuery = q.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, "\\$&");
  const wordBoundaryRegex = new RegExp(`(^|\\s)${escapedQuery}`, "i");

  const matches = options.filter((option) => {
    const name = (option.bank_name || option.label || "").toLowerCase();
    const ifsc = (option.ifsc_code || "").toLowerCase();
    return name.includes(q) || ifsc.includes(q);
  });

  return matches.sort((a, b) => {
    const nameA = (a.bank_name || a.label || "").toLowerCase();
    const nameB = (b.bank_name || b.label || "").toLowerCase();

    // 1. Exact name match
    const exactA = nameA === q;
    const exactB = nameB === q;
    if (exactA && !exactB) return -1;
    if (!exactA && exactB) return 1;

    // 2. Starts with query (e.g. typing "central" matches "CENTRAL BANK OF INDIA", "CENTRAL CO-OP BANK")
    const startsA = nameA.startsWith(q);
    const startsB = nameB.startsWith(q);
    if (startsA && !startsB) return -1;
    if (!startsA && startsB) return 1;

    // 3. Word starts with query (word-boundary match e.g. "THE CENTRAL ...")
    const wordA = wordBoundaryRegex.test(nameA);
    const wordB = wordBoundaryRegex.test(nameB);
    if (wordA && !wordB) return -1;
    if (!wordA && wordB) return 1;

    // 4. Alphabetical tie-break
    return (a.bank_name || a.label || "").localeCompare(b.bank_name || b.label || "", undefined, {
      sensitivity: "base",
    });
  });
};

