/* ------------------------------------------------------------
   Charge breakdown grid — mirrors the "Remitter No / Bank /
   Beneficiary Name / Account Number / Total Amount / Deduction /
   CCF / Commission / TDS" table from the reference screenshot.
   Field names on `chargeDetails` are a best guess (the backend
   response from sendbank3MoneyTransdmt / sendMoneyTrans isn't
   documented here) — rename the keys below to match whatever the
   API actually returns; everything falls back to "—" until then.
   ------------------------------------------------------------ */
const ChargeDetailCell = ({
  label,
  value,
  highlight = false,
  isBold = false,
  spanFull = false,
}) => (
  <Box
    sx={{
      px: { xs: 1, sm: 1.25 },
      py: 0.55,
      borderRight: `1px solid ${LINE}`,
      borderBottom: `1px solid ${LINE}`,
      minWidth: 0,
      gridColumn: spanFull ? "span 2" : "span 1",
      backgroundColor: highlight ? "rgba(31,143,115,0.06)" : "transparent",
      display: "flex",
      flexDirection: "column",
      justifyContent: "center",
    }}
  >
    <Typography
      sx={{
        fontSize: 9.5,
        color: MUTED,
        fontFamily: FONT_UI,
        fontWeight: 600,
        mb: 0.15,
        letterSpacing: "0.2px",
        lineHeight: 1.1,
      }}
    >
      {label}
    </Typography>
    <Typography
      sx={{
        fontSize: isBold ? 13 : 11.5,
        color: highlight ? PRIMARY : NAVY_TEXT,
        fontFamily: FONT_MONO,
        fontWeight: isBold ? 800 : 700,
        lineHeight: 1.15,
      }}
      noWrap
      title={String(value)}
    >
      {value ?? "—"}
    </Typography>
  </Box>
);

const ChargeBreakdown = ({
  recipient,
  bankDisplayName,
  amount,
  customer,
  chargeDetails,
  transferMode,
}) => {
  const numAmount = Number(amount) || 0;

  // 1. Dynamic CCF Charges
  const ccfVal =
    chargeDetails?.ccf_amount !== undefined && chargeDetails?.ccf_amount !== null
      ? Number(chargeDetails.ccf_amount)
      : numAmount > 0
        ? +(numAmount * 0.01).toFixed(2)
        : 0;

  // 2. Dynamic Retailer Commission (R Commission)
  const rCommVal =
    chargeDetails?.r_commission !== undefined && chargeDetails?.r_commission !== null
      ? Number(chargeDetails.r_commission)
      : chargeDetails?.commission_amount !== undefined && chargeDetails?.commission_amount !== null
        ? Number(chargeDetails.commission_amount)
        : 0;

  // 3. Dynamic Distributor Commission
  const distCommVal =
    chargeDetails?.dist_commission !== undefined && chargeDetails?.dist_commission !== null
      ? Number(chargeDetails.dist_commission)
      : chargeDetails?.distributor_commission !== undefined && chargeDetails?.distributor_commission !== null
        ? Number(chargeDetails.distributor_commission)
        : 0;

  // 4. Dynamic Super Distributor Commission (S.D Commission)
  const sdCommVal =
    chargeDetails?.sd_commission !== undefined && chargeDetails?.sd_commission !== null
      ? Number(chargeDetails.sd_commission)
      : chargeDetails?.super_distributor_commission !== undefined && chargeDetails?.super_distributor_commission !== null
        ? Number(chargeDetails.super_distributor_commission)
        : 0;

  // 5. Dynamic TDS on Commission (2%)
  const tdsVal =
    chargeDetails?.tds_amount !== undefined && chargeDetails?.tds_amount !== null
      ? Number(chargeDetails.tds_amount)
      : +(rCommVal * 0.02).toFixed(2);

  // 6. Dynamic Actual Deducted (Net Fee): CCF - Retailer Commission
  const actualDeductedVal =
    chargeDetails?.actual_deducted !== undefined &&
      chargeDetails?.actual_deducted !== null
      ? Number(chargeDetails.actual_deducted)
      : +(ccfVal - rCommVal).toFixed(2);

  // 7. Dynamic Total Deduction (Total Wallet Debit): Amount + Actual Deducted + TDS
  const totalDeductionVal =
    (chargeDetails?.deduction_amount || chargeDetails?.total_deduction) !==
      undefined
      ? Number(chargeDetails?.deduction_amount || chargeDetails?.total_deduction)
      : +(numAmount + actualDeductedVal + tdsVal).toFixed(2);

  const txnCount =
    chargeDetails?.transaction_count ||
    (numAmount > 0 ? Math.ceil(numAmount / 5000) : 1);

  const channelText =
    transferMode === "1" ? "NEFT" : transferMode === "2" ? "IMPS" : (transferMode || "IMPS");

  const cells = [
    {
      label: "Beneficiary Name",
      value: recipient?.bank_account_name || recipient?.recipient_name || "—",
    },
    {
      label: "Bank Name",
      value: bankDisplayName || recipient?.bank || "—",
    },
    {
      label: "Remitter Mob No.",
      value: customer?.mobile || "—",
    },
    {
      label: "Account Number",
      value: recipient?.account || "—",
    },
    {
      label: "Total Amount",
      value: numAmount > 0 ? `₹${numAmount}` : "—",
      isBold: true,
    },
    {
      label: "CCF @ 1% (Min. INR 10)",
      value: `₹${ccfVal.toFixed(2)}`,
    },
    {
      label: "Retailer Commission (R)",
      value: `₹${rCommVal.toFixed(2)}`,
    },
    {
      label: "TDS on Commission",
      value: `₹${tdsVal.toFixed(2)}`,
    },
    {
      label: "Actual deducted",
      value: `₹${actualDeductedVal.toFixed(2)}`,
    },
    {
      label: "Deduction",
      value: `₹${totalDeductionVal.toFixed(2)}`,
      highlight: true,
      isBold: true,
    },
    {
      label: "Channel",
      value: channelText,
    },
    {
      label: "Split Status",
      value: txnCount > 1 ? `Divided into ${txnCount} txns` : "Single transaction",
    },
  ];

  return (
    <Box sx={{ textAlign: "left", mb: 1.25 }}>
      <Box
        sx={{
          borderTop: `1px solid ${LINE}`,
          borderLeft: `1px solid ${LINE}`,
          borderRadius: "8px",
          overflow: "hidden",
          display: "grid",
          gridTemplateColumns: "repeat(2, 1fr)",
        }}
      >
        {cells.map((cell) => (
          <ChargeDetailCell
            key={cell.label}
            label={cell.label}
            value={cell.value}
            highlight={cell.highlight}
            isBold={cell.isBold}
            spanFull={cell.spanFull}
          />
        ))}
      </Box>
    </Box>
  );
};

const SendMoneyPopup = ({
  otpResponse,
  setOtpResponse,
  amount,
  transferMode,
  otpSent,
  open,
  onClose,
  recipient,
  chargeDetails,
}) => {
  const {
    setInvoiceId,
    setCurrentPage,
    walletCall,
    setGlobalLoader,
    customer,
    selectedBank,
    allBank,
  } = useBankTransfer();
  const naviagte = useNavigate();
  const [amountError, setAmountError] = useState("");

  const [otp, setOtp] = useState("");
  const [otpError, setOtpError] = useState("");
  const [otpVerified, setOtpVerified] = useState(false);
  const [pin, setPin] = useState("");
  const [pinError, setPinError] = useState("");

  const [otpLoading, setOtpLoading] = useState(false);
  const [moneyLoading, setMoneyLoading] = useState(false);

  // Once the money-transfer call succeeds, swap the dialog body over to
  // the transaction-history view instead of just closing.
  const [transferComplete, setTransferComplete] = useState(false);

  const totalLimit = customer?.total_limit || 0;
  const usedLimit = customer?.used_limit || 0;
  const availableLimit = totalLimit - usedLimit;

  const bankNameObj = allBank.find((item) => item?._id === selectedBank);
  const bankName = bankNameObj?.name || "";
  const isInstantpayBank = isInstantpayBankHelper(bankNameObj);

  const validateOtp = (value) => {
    if (!value) return "OTP is required";
    if (!/^\d{6}$/.test(value)) return "OTP must be 6 digits";
    return "";
  };

  const validatePin = (value) => {
    if (!value) return "PIN is required";
    if (!/^\d{4}$/.test(value)) return "PIN must be 4 digits";
    return "";
  };

  const handleSubmitOtp = () => {
    const err = validateOtp(otp);
    setOtpError(err);
    if (!err) {
      setOtpVerified(true);
    }
  };

  const handleSendMoney = withLocation(async (latitude, longitude) => {
    const pinErr = validatePin(pin);
    setPinError(pinErr);
    if (!pinErr) {
      setMoneyLoading(true);
      let body = {
        recipient_id: recipient.recipient_id,
        amount: amount,
        customer_mobile: customer?.mobile || recipient?.recipient_mobile,
        channel: transferMode,
        beneficiary_name:
          recipient?.bank_account_name || recipient?.recipient_name,
        bank_name: recipient.bank,
        ifsc_code: recipient.ifsc,
        account_number: recipient.account,
        customer_name: customer?.name,
        api_id: selectedBank,
        user_id: window.localStorage.getItem("userIdToken"),
        latlong: `${latitude},${longitude}`,
        tpin: pin,
      };
      // Send OTP and reference value for Instantpay pipes (AB, JD, ND)
      // Old: if (bankName === "bank1") { ... }
      if (isInstantpayBank || bankName === "bank1") {
        body.otp = otp;
        body.value = otpResponse;
      }
      try {
        const res = await sendMoneyTrans(body);
        toastMessage(res?.data?.error, res?.data?.message);
        if (
          res?.data?.statusCode === "200" ||
          res?.data?.statusCode === "127"
        ) {
          setInvoiceId(res?.data?.data?.[0]?.batchId);
          walletCall();
          // Show the transaction-history view inside this dialog instead
          // of immediately jumping away — the person can still open the
          // full invoice from here.
          setTransferComplete(true);
        }
        if (res?.data?.statusCode === "400") {
          setTimeout(() => {
            onClose();
          }, 400);
        }

        if (res?.data?.statusCode === "405") {
          onClose();
          setOtpResponse("");
          setOtpVerified(false);
          otpSent(false);
        }

        setTimeout(() => {
          setPin("");
        }, 500);
      } catch (error) {
      } finally {
        setMoneyLoading(false);
      }
    }
  });

  const renderStep = () => {
    // Old implementation kept for reference / safety:
    // const showOtpInput = bankName === "bank1" && otpSent && !otpVerified;
    // const showPinInput = (bankName === "bank1" && otpVerified) || (bankName === "bank2" && otpSent);
    const showOtpInput = (isInstantpayBank || bankName === "bank1") && otpSent && !otpVerified;
    const showPinInput =
      ((isInstantpayBank || bankName === "bank1") && otpVerified) ||
      (!isInstantpayBank && otpSent);

    return (
      <>
        {showOtpInput && (
          <Box sx={{ mt: 0.5 }}>
            <CustomTextField
              fullWidth
              label="Enter 6-Digit OTP"
              placeholder={"Enter 6 Digit Otp"}
              value={otp}
              onChange={(e) => {
                const value = e.target.value;
                if (/^\d{0,6}$/.test(value)) {
                  setOtp(value);
                }
              }}
              inputProps={{ maxLength: 6 }}
              error={!!otpError}
              helperText={otpError}
              size="small"
            />
            <Box sx={{ display: "flex", gap: 1.5, mt: 1.25 }}>
              <Button
                variant="outlined"
                onClick={onClose}
                sx={{
                  ...outlineBtnSx,
                  flex: 1,
                  py: 0.8,
                  height: 38,
                  borderRadius: "50px",
                  fontSize: "13px",
                }}
              >
                Cancel
              </Button>
              <Button
                variant="contained"
                onClick={handleSubmitOtp}
                sx={{
                  ...gradientBtnSx(!otp || otp.length !== 6 || otpLoading),
                  flex: 2,
                  py: 0.8,
                  height: 38,
                  fontSize: "13px",
                }}
                disabled={!otp || otp.length != 6 || otpLoading}
              >
                {otpLoading ? "Verifying..." : "Submit OTP"}
              </Button>
            </Box>
          </Box>
        )}

        {showPinInput && (
          <Box sx={{ mt: 0.5 }}>
            <CustomTextField
              fullWidth
              label="Enter 4-Digit T-PIN"
              type="password"
              placeholder="Enter 4-digit PIN"
              value={pin}
              onChange={(e) => {
                const value = e.target.value;
                if (/^\d{0,4}$/.test(value)) {
                  setPin(value);
                }
              }}
              inputProps={{ maxLength: 4 }}
              error={!!pinError}
              helperText={pinError}
              size="small"
            />
            <Box sx={{ display: "flex", gap: 1.5, mt: 1.25 }}>
              <Button
                variant="outlined"
                onClick={onClose}
                sx={{
                  ...outlineBtnSx,
                  flex: 1,
                  py: 0.8,
                  height: 38,
                  borderRadius: "50px",
                  fontSize: "13px",
                }}
              >
                Cancel
              </Button>
              <Button
                variant="contained"
                onClick={handleSendMoney}
                sx={{
                  ...gradientBtnSx(pin.length !== 4 || moneyLoading),
                  flex: 2,
                  py: 0.8,
                  height: 38,
                  fontSize: "13px",
                }}
                disabled={pin.length != 4 || moneyLoading}
              >
                {moneyLoading ? "Sending..." : "Send Money"}
              </Button>
            </Box>
          </Box>
        )}
      </>
    );
  };

  return (
    <Dialog
      open={open}
      maxWidth="sm"
      fullWidth
      onClose={() => { }}
      disableEscapeKeyDown
      disableBackdropClick
      TransitionComponent={Grow}
      PaperProps={{
        onClick: (e) => e.stopPropagation(),
        sx: {
          borderRadius: "16px",
          overflow: "hidden",
          maxHeight: "96vh",
        },
      }}
    >
      <DialogContent sx={{ textAlign: "center", p: { xs: 2, sm: 2.25 }, overflowY: "hidden" }}>
        {!transferComplete ? (
          <>
            {/* Sleek Compact Header */}
            <Box
              sx={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                mb: 1.25,
                pb: 1,
                borderBottom: `1px solid ${LINE}`,
              }}
            >
              <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                <Box
                  sx={{
                    width: 32,
                    height: 32,
                    borderRadius: "8px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    background: "rgba(185,138,70,0.12)",
                    color: GOLD,
                    flexShrink: 0,
                  }}
                >
                  <LockIcon sx={{ fontSize: 18 }} />
                </Box>
                <Box sx={{ textAlign: "left" }}>
                  <Typography
                    sx={{
                      fontWeight: 800,
                      fontFamily: FONT_DISPLAY,
                      fontSize: 15.5,
                      color: NAVY_TEXT,
                      lineHeight: 1.2,
                    }}
                  >
                    Send Money Confirmation
                  </Typography>
                  <Typography sx={{ color: MUTED, fontFamily: FONT_UI, fontSize: 11, lineHeight: 1.2 }}>
                    {otpSent && !otpVerified
                      ? "Enter the 6-digit OTP sent to customer mobile"
                      : "Enter your 4-digit TPIN to complete transfer"}
                  </Typography>
                </Box>
              </Box>
              <IconButton
                onClick={onClose}
                size="small"
                sx={{
                  color: MUTED,
                  p: 0.5,
                  "&:hover": { color: NAVY_TEXT, backgroundColor: "rgba(0,0,0,0.05)" },
                }}
              >
                <CloseIcon sx={{ fontSize: 18 }} />
              </IconButton>
            </Box>

            {otpSent && (
              <ChargeBreakdown
                recipient={recipient}
                bankDisplayName={getBankDisplayName(bankNameObj)?.toUpperCase()}
                amount={amount}
                customer={customer}
                chargeDetails={chargeDetails}
                transferMode={transferMode}
              />
            )}

            <Box mt={0.5} textAlign="left">
              {renderStep()}
            </Box>
          </>
        ) : (
          <>
            <IconBadge icon={<CheckCircle sx={{ color: "#0A0F1C", fontSize: 24 }} />} />
            <Typography
              sx={{ fontWeight: 800, fontFamily: FONT_DISPLAY, fontSize: 19, color: NAVY_TEXT, mb: 0.5 }}
            >
              Money Sent
            </Typography>
            <Typography sx={{ color: MUTED, fontFamily: FONT_DISPLAY, fontSize: 13, mb: 1 }}>
              ₹{amount} sent to {recipient?.bank_account_name || recipient?.recipient_name}
            </Typography>
            <Box textAlign="left">
              <TransactionHistoryPanel mobile={customer?.mobile} apiId={selectedBank} />
            </Box>
          </>
        )}
      </DialogContent>

      {transferComplete && (
        <DialogActions sx={{ justifyContent: "center", pb: 2.5, gap: 1.5 }}>
          <Button variant="outlined" sx={outlineBtnSx} onClick={onClose}>
            Done
          </Button>
          <Button
            variant="contained"
            sx={gradientBtnSx(false)}
            onClick={() => {
              onClose();
              setCurrentPage("invoice");
            }}
          >
            View Invoice
          </Button>
        </DialogActions>
      )}
    </Dialog>
  );
};

