const KYCPage = () => {
  const devices = [
    { id: "2", img: imgg2, name: "Mantra" },
    { id: "3", img: imgg3, name: "Mantra L1" },
    { id: "4", img: imgg4, name: "Morpho" },
  ];
  const { walletCall, wadhValue, selectedBank, mobile, setCurrentPage } = useBankTransfer();
  const [selectedDeviceId, setSelectedDeviceId] = useState(null);

  const { loading, captureFingerprint } = useFingerprintCapture({ wadhValue });

  const handleDeviceSelect = (id) => {
    setSelectedDeviceId(id);
  };

  const selectedDevice = devices.find((d) => d.id === selectedDeviceId);

  const handleCaptureFingerprint = withLocation(async (latitude, longitude) => {
    if (!selectedDevice) return alert("Please select a device.");

    try {
      const result = await captureFingerprint(selectedDevice.name);
      const xmlStr = result.pidData + "<bookz/>";
      const encodedXml = window.btoa(
        new XMLSerializer().serializeToString(
          new DOMParser().parseFromString(xmlStr, "application/xml")
        )
      );

      const body = {
        customer_mobile: mobile,
        latitude,
        longitude,
        biometric_data: encodedXml,
        api_id: selectedBank,
      };

      const res = await dmtkycapi(body);
      if (res?.data?.statusCode === "200" && !res?.data?.error) {
        setCurrentPage("send-money-page");
        walletCall();
      }
      toastMessage(res?.data?.error, res?.data?.message);
    } catch (error) {
      alert("Capture failed: " + error.message);
    }
  });

  return (
    <>
      <CustomBox>
        <PageHeader
          title="Verify KYC"
          subtitle="Pick the connected device and capture a fingerprint to continue"
          onBack={() => setCurrentPage("money-transfer")}
        />

        <Grid container spacing={2} sx={{ p: 2 }}>
          <Grid item xs={12}>
            <Grid container spacing={2}>
              {devices?.map((device, index) => (
                <Grid item xs={6} sm={4} md={2} key={index}>
                  <Card
                    onClick={() => handleDeviceSelect(device.id)}
                    sx={{
                      display: "flex",
                      flexDirection: "column",
                      alignItems: "center",
                      p: 1,
                      height: "100%",
                      border: selectedDeviceId === device.id ? `1.5px solid ${PRIMARY}` : `1px solid ${LINE}`,
                      backgroundColor: selectedDeviceId === device.id ? "rgba(185,138,70,0.08)" : "#FFFFFF",
                      borderRadius: 2,
                      boxShadow: 0,
                      cursor: "pointer",
                      transition: "all 0.2s ease",
                    }}
                  >
                    <CardMedia
                      component="img"
                      image={device.img}
                      alt={device.name}
                      sx={{ height: 80, objectFit: "contain", mb: 1 }}
                    />
                    <CardContent sx={{ p: 0 }}>
                      <Typography variant="body2" align="center" sx={{ fontWeight: 500, fontFamily: FONT_DISPLAY, color: NAVY_TEXT }}>
                        {device.name}
                      </Typography>
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>
          </Grid>

          <Grid item xs={12} textAlign="center">
            <Button
              variant="contained"
              disabled={!selectedDeviceId || loading}
              onClick={handleCaptureFingerprint}
              sx={{ mt: 3, ...gradientBtnSx(!selectedDeviceId || loading) }}
            >
              {loading ? "Capturing..." : "Capture Fingerprint"}
            </Button>
          </Grid>
        </Grid>
      </CustomBox>
    </>
  );
};

const InvoiceRecord = () => {
  const [loading, setLoading] = useState(false);

  const { invoiceId, setCurrentPage } = useBankTransfer();
  const [data, setData] = useState(null);

  const ref = useRef();

  const handlePrint = useReactToPrint({
    content: () => ref.current,
    documentTitle: "DMT Data",
  });

  const handleDownloadThermal = () => {
    const element = document.getElementById("contentId1");
    const opt = {
      margin: 1,
      format: [90, 297],
      filename: "thermal_print_page.pdf",
      image: { type: "jpeg", quality: 0.98 },
      html2canvas: { scale: 2 },
      jsPDF: { unit: "mm", format: [110, 200], orientation: "portrait" },
    };
    html2pdf().set(opt).from(element).save();
  };

  const dataDetails = async () => {
    setLoading(true);
    try {
      const res = await dmtDtails(invoiceId);
      setData(res?.data?.data);
    } catch (error) { }
    setLoading(false);
  };
  useEffect(() => {
    dataDetails();
  }, [invoiceId]);

  const scrollRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = 0;
    }
  }, []);

  const executeScroll = () => {
    scrollRef?.current?.scrollIntoView({
      behavior: "smooth",
      block: "end",
    });
  };

  useEffect(() => {
    executeScroll();
  }, []);
  return (
    <>
      {loading && <Loader />}
      <div ref={scrollRef}></div>
      <div className="ContentArea">
        <div className="card">
          <div className="card-header card-Details">
            <div className="d-flex align-items-center">
              <IconButton onClick={() => setCurrentPage("send-money-page")}>
                <ArrowBackIosNewIcon />
              </IconButton>
              <div className="Details">
                <span>Details</span>
              </div>
            </div>

            <div className="button-print">
              <div type="button" className="btn btn-warning mr-3" onClick={handlePrint}>
                {" "}
                <IoMdPrint />
                Full Print
              </div>
              <div type="button" className="btn btn-warning mr-3" onClick={handleDownloadThermal}>
                {" "}
                <IoMdPrint />
                Thermal Print
              </div>
            </div>
          </div>
          <div ref={ref} id="contentId1" className="contentId2">
            <div className="card-body">
              <div className="row">
                <div className="col-lg-12">
                  <div className="logo-print text-align-center pb-3">
                    <img src={image} alt="" />
                  </div>
                </div>

                <div className="col-lg-6 aabc">
                  <div className="left-side-section">
                    <div>
                      CSP Name :{" "}
                      <span style={{ color: NAVY_TEXT }}>{data?.invoice[0]?.shop_name}</span>
                    </div>
                    <div>
                      Mobile Number :{" "}
                      <span style={{ color: NAVY_TEXT }}>{data?.invoice[0]?.mobile_number}</span>
                    </div>
                    <div>
                      Sender Name :{" "}
                      <span style={{ color: NAVY_TEXT }}>{data?.invoice[0]?.customer_name}</span>
                    </div>
                    <div>
                      Sender No :{" "}
                      <span style={{ color: NAVY_TEXT }}>{data?.invoice[0]?.customer_mobile}</span>
                    </div>
                  </div>
                </div>
                <div className="col-lg-6 aabc">
                  <div className="right-side-section">
                    <div>
                      Beneficiary :{" "}
                      <span style={{ color: NAVY_TEXT }}>{data?.invoice[0]?.beneficiary_name}</span>
                    </div>
                    <div>
                      Bank Name :{" "}
                      <span style={{ color: NAVY_TEXT }}>{data?.invoice[0]?.bank_name}</span>
                    </div>

                    <div>
                      Account No :{" "}
                      <span style={{ color: NAVY_TEXT }}>{data?.invoice[0]?.account_number}</span>
                    </div>
                    <div>
                      Date :{" "}
                      <span style={{ color: NAVY_TEXT }}>{data?.invoice[0]?.createdAt}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="col-lg-12">
              <div className="card mt-4" style={{ overflow: "auto" }}>
                <div className="card-body">
                  <div id="myTable_wrapper" className="dataTables_wrapper no-footer">
                    <table
                      className="table table-striped table-bordered table-hover display dataTable no-footer dtr-inline collapsed"
                      role="grid"
                      aria-describedby="myTable_info"
                    >
                      <thead>
                        <tr role="row">
                          <th className="sorting">TID</th>
                          <th className="sorting">Status</th>
                          <th className="sorting">UTR No</th>
                          <th className="sorting">Amount</th>
                        </tr>
                      </thead>
                      <tbody>
                        {data &&
                          data?.invoice[0]?.allTrans?.map((item) => {
                            return (
                              <tr key={item?._id}>
                                <td valign="top" className="dataTables_empty">{item?.tid}</td>
                                <td valign="top" className="dataTables_empty">{item?.status}</td>
                                <td valign="top" className="dataTables_empty">{item?.utr}</td>
                                <td valign="top" className="dataTables_empty">{item?.amount}</td>
                              </tr>
                            );
                          })}
                        <tr>
                          <td valign="top" className="dataTables_empty" colSpan={3}>
                            Total
                          </td>
                          <td valign="top" className="dataTables_empty">
                            {data?.invoice[0]?.totalAmount}
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>

                  <div className="col-lg-12">
                    <div className="reserve">
                      <p>© {new Date()?.getFullYear()} All Rights Reserved </p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

const TxnStatusChip = ({ status }) => {
  const s = (status ?? "").toString().toLowerCase();
  const isSuccess = ["success", "200", "127", "completed", "credited"].includes(s);
  const isFailed = ["failed", "400", "declined", "reversed", "error"].includes(s);
  const isPending = ["pending", "processing", "initiated"].includes(s);
  const color = isSuccess ? SUCCESS : isFailed ? DANGER : isPending ? GOLD : MUTED;
  return (
    <Chip
      label={status || "Unknown"}
      size="small"
      sx={{
        height: 22,
        fontSize: 11,
        fontWeight: 700,
        textTransform: "capitalize",
        fontFamily: FONT_UI,
        color,
        backgroundColor: `${color}1A`,
        border: `1px solid ${color}33`,
      }}
    />
  );
};

const TransactionHistoryPanel = ({ mobile, apiId, compact = false, dialogMode = false }) => {
  const [txns, setTxns] = useState([]);
  const [loading, setLoading] = useState(false);
  const [errored, setErrored] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const [filterTerm, setFilterTerm] = useState("");

  useEffect(() => {
    let active = true;
    const fetchHistory = async () => {
      if (!isValidIndianMobile(mobile) || !apiId) return;
      setLoading(true);
      setErrored(false);
      try {
        const res = await dmtTransiList({ mobile, api_id: apiId });
        if (!active) return;
        const list = res?.data?.data;
        const safeList = Array.isArray(list) ? list : [];
        // Defensive: the endpoint is named "report/all", so filter to this
        // customer's mobile client-side in case the API doesn't already
        // scope results to the mobile/api_id passed in.
        const scoped = safeList.filter(
          (txn) =>
            !mobile ||
            txn?.customer_mobile === mobile ||
            txn?.mobile === mobile ||
            txn?.sender_mobile === mobile
        );
        setTxns(scoped.length ? scoped : safeList);
      } catch (err) {
        if (!active) return;
        setErrored(true);
        setTxns([]);
      } finally {
        if (active) setLoading(false);
      }
    };
    fetchHistory();
    return () => {
      active = false;
    };
  }, [mobile, apiId, refreshKey]);

  if (dialogMode) {
    const displayedTxns = txns.filter((txn) => {
      if (!filterTerm.trim()) return true;
      const q = filterTerm.trim().toLowerCase();
      return (
        txn?.beneficiary_name?.toLowerCase?.().includes(q) ||
        txn?.recipient_name?.toLowerCase?.().includes(q) ||
        txn?.account?.toLowerCase?.().includes(q) ||
        txn?.account_number?.toLowerCase?.().includes(q) ||
        txn?.bank?.toLowerCase?.().includes(q) ||
        txn?.bank_name?.toLowerCase?.().includes(q) ||
        txn?.utr?.toLowerCase?.().includes(q) ||
        txn?.tid?.toLowerCase?.().includes(q)
      );
    });

    return (
      <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5 }}>
        <Box display="flex" alignItems="center" justifyContent="space-between" gap={1} flexWrap="wrap">
          <CustomTextField
            placeholder="Search by name, account, UTR, TID..."
            value={filterTerm}
            onChange={(e) => setFilterTerm(e.target.value)}
            InputProps={{ startAdornment: <SearchIcon sx={{ fontSize: 16, color: MUTED, mr: 0.75 }} /> }}
            sx={{ flex: 1, minWidth: 220, "& .MuiOutlinedInput-root": { height: 36 } }}
          />
          <Stack direction="row" spacing={1} alignItems="center">
            <Typography sx={{ fontSize: 12, color: MUTED, fontFamily: FONT_UI }}>
              {loading ? "Loading..." : `${displayedTxns.length} transaction${displayedTxns.length === 1 ? "" : "s"}`}
            </Typography>
            <Tooltip title="Refresh">
              <IconButton
                size="small"
                onClick={() => setRefreshKey((k) => k + 1)}
                sx={{
                  color: NAVY_TEXT,
                  border: `1px solid ${LINE}`,
                  borderRadius: "8px",
                  p: 0.75,
                  "&:hover": { borderColor: GOLD, backgroundColor: "rgba(185,138,70,0.06)" },
                }}
              >
                <RefreshIcon sx={{ fontSize: 18 }} />
              </IconButton>
            </Tooltip>
          </Stack>
        </Box>

        {loading && (
          <Stack spacing={1}>
            {[0, 1, 2, 3, 4].map((i) => (
              <Skeleton key={i} variant="rounded" height={64} sx={{ borderRadius: "10px" }} />
            ))}
          </Stack>
        )}

        {!loading && errored && (
          <Box
            sx={{
              p: 2,
              borderRadius: "10px",
              border: `1px dashed ${DANGER}55`,
              backgroundColor: "rgba(220,38,38,0.05)",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <Typography sx={{ fontSize: 13, color: DANGER, fontFamily: FONT_UI }}>
              Couldn't load transaction history right now.
            </Typography>
            <Button size="small" variant="outlined" onClick={() => setRefreshKey((k) => k + 1)} sx={{ ...outlineBtnSx, height: 28, fontSize: 11 }}>
              Retry
            </Button>
          </Box>
        )}

        {!loading && !errored && displayedTxns.length === 0 && (
          <Box
            sx={{
              p: 4,
              textAlign: "center",
              borderRadius: "10px",
              border: `1px dashed ${LINE}`,
              backgroundColor: "rgba(148,163,184,0.04)",
            }}
          >
            <ReceiptLongIcon sx={{ fontSize: 36, color: "text.disabled", mb: 1 }} />
            <Typography sx={{ fontSize: 14, fontWeight: 600, color: NAVY_TEXT, fontFamily: FONT_DISPLAY }}>
              {filterTerm ? "No matching transactions found" : "No past transactions found"}
            </Typography>
            <Typography sx={{ fontSize: 12, color: MUTED, fontFamily: FONT_UI, mt: 0.5 }}>
              {filterTerm ? "Try a different search query." : "Transactions on this bank for this customer will appear here."}
            </Typography>
          </Box>
        )}

        {!loading && !errored && displayedTxns.length > 0 && (
          <Stack spacing={1}>
            {displayedTxns.map((txn, idx) => {
              const dateStr = txn?.createdAt
                ? new Date(txn.createdAt).toLocaleString("en-IN", {
                  day: "2-digit",
                  month: "short",
                  year: "numeric",
                  hour: "2-digit",
                  minute: "2-digit",
                  hour12: true,
                })
                : "";
              const accountNum = txn?.account || txn?.account_number;
              const bankNameStr = txn?.bank || txn?.bank_name;
              return (
                <Box
                  key={txn?._id || txn?.tid || idx}
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: 1.5,
                    p: 1.5,
                    borderRadius: "10px",
                    border: `1px solid ${LINE}`,
                    backgroundColor: "#FFFFFF",
                    boxShadow: "0 1px 4px rgba(16,27,52,0.03)",
                    transition: "border-color 0.15s ease",
                    "&:hover": { borderColor: GOLD },
                  }}
                >
                  <Box sx={{ minWidth: 0, flex: 1 }}>
                    <Box display="flex" alignItems="center" gap={1} mb={0.25}>
                      <Typography sx={{ fontSize: 13.5, fontWeight: 700, color: NAVY_TEXT, fontFamily: FONT_DISPLAY }} noWrap>
                        {txn?.beneficiary_name || txn?.recipient_name || "Beneficiary"}
                      </Typography>
                      {txn?.channel && (
                        <Chip
                          label={txn.channel.toUpperCase()}
                          size="small"
                          sx={{ height: 18, fontSize: 10, fontWeight: 700, fontFamily: FONT_MONO, backgroundColor: "rgba(16,27,52,0.06)", color: NAVY_TEXT }}
                        />
                      )}
                    </Box>
                    <Box display="flex" alignItems="center" gap={0.75} flexWrap="wrap">
                      {accountNum && (
                        <Typography sx={{ fontSize: 11.5, color: NAVY_TEXT, fontFamily: FONT_MONO }}>
                          A/C: {accountNum}
                        </Typography>
                      )}
                      {bankNameStr && (
                        <Typography sx={{ fontSize: 11, color: GOLD, fontFamily: FONT_DISPLAY, fontWeight: 600 }}>
                          · {bankNameStr}
                        </Typography>
                      )}
                      {(txn?.utr || txn?.tid) && (
                        <Typography sx={{ fontSize: 11, color: MUTED, fontFamily: FONT_MONO }}>
                          · {txn?.utr ? `UTR: ${txn.utr}` : `TID: ${txn.tid}`}
                        </Typography>
                      )}
                      {dateStr && (
                        <Typography sx={{ fontSize: 11, color: MUTED, fontFamily: FONT_UI }}>
                          · {dateStr}
                        </Typography>
                      )}
                    </Box>
                  </Box>
                  <Stack direction="column" spacing={0.3} alignItems="flex-end" flexShrink={0}>
                    <Typography sx={{ fontSize: 14.5, fontWeight: 700, color: PRIMARY, fontFamily: FONT_MONO }}>
                      ₹{txn?.amount ?? txn?.transfer_amount ?? 0}
                    </Typography>
                    <Typography sx={{ fontSize: 10.5, color: MUTED, fontFamily: FONT_MONO }}>
                      Deduction: ₹{txn?.total_deduction ?? (Number(txn?.amount || 0) + Number(txn?.charge || 0)).toFixed(2)}
                    </Typography>
                    <TxnStatusChip status={txn?.status} />
                  </Stack>
                </Box>
              );
            })}
          </Stack>
        )}
      </Box>
    );
  }

  return (
    <Box sx={compact ? { pt: 0.25 } : { mt: 2, pt: 1.5, borderTop: `1px dashed ${LINE}` }}>
      <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ mb: compact ? 0.5 : 1.25 }}>
        <Typography
          sx={{
            fontFamily: FONT_UI,
            fontSize: compact ? 10.5 : 11,
            fontWeight: 700,
            letterSpacing: "1.4px",
            color: GOLD,
          }}
        >
          RECENT ACTIVITY
        </Typography>
        <Tooltip title="Refresh">
          <IconButton size="small" onClick={() => setRefreshKey((k) => k + 1)} sx={{ color: MUTED, p: 0.25 }}>
            <RefreshIcon sx={{ fontSize: compact ? 16 : 18 }} />
          </IconButton>
        </Tooltip>
      </Stack>

      <Typography sx={{ fontSize: compact ? 11 : 12.5, color: MUTED, fontFamily: FONT_UI, mb: compact ? 0.75 : 1.5 }}>
        Transactions for this number on the selected bank.
      </Typography>

      {loading && (
        <Stack spacing={0.75}>
          {[0, 1, 2].map((i) => (
            <Skeleton key={i} variant="rounded" height={compact ? 40 : 52} sx={{ borderRadius: "8px" }} />
          ))}
        </Stack>
      )}

      {!loading && errored && (
        <Box
          sx={{
            p: 1.25,
            borderRadius: "8px",
            border: `1px dashed ${DANGER}55`,
            backgroundColor: "rgba(220,38,38,0.05)",
          }}
        >
          <Typography sx={{ fontSize: 11.5, color: DANGER, fontFamily: FONT_UI }}>
            Couldn't load transaction history right now.
          </Typography>
        </Box>
      )}

      {!loading && !errored && txns.length === 0 && (
        <Box
          sx={{
            p: compact ? 1.5 : 2.5,
            textAlign: "center",
            borderRadius: "8px",
            border: `1px dashed ${LINE}`,
            backgroundColor: "rgba(148,163,184,0.06)",
          }}
        >
          <ReceiptLongIcon sx={{ fontSize: compact ? 22 : 26, color: "text.disabled", mb: 0.25 }} />
          <Typography sx={{ fontSize: compact ? 11.5 : 12.5, color: MUTED, fontFamily: FONT_UI }}>
            No past transactions found for this number on this bank yet.
          </Typography>
        </Box>
      )}

      {!loading && !errored && txns.length > 0 && (
        <Stack spacing={0.75}>
          {txns.slice(0, 6).map((txn, idx) => (
            <Box
              key={txn?._id || txn?.tid || idx}
              sx={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                gap: 1,
                p: compact ? "6px 10px" : 1.25,
                borderRadius: "8px",
                border: `1px solid ${LINE}`,
                backgroundColor: "#FFFFFF",
              }}
            >
              <Box sx={{ minWidth: 0, flex: 1 }}>
                <Typography
                  sx={{ fontSize: compact ? 12 : 13, fontWeight: 600, color: NAVY_TEXT, fontFamily: FONT_DISPLAY }}
                  noWrap
                >
                  {txn?.beneficiary_name || txn?.recipient_name || "Beneficiary"}
                </Typography>
                <Typography sx={{ fontSize: compact ? 10.5 : 11, color: MUTED, fontFamily: FONT_MONO }} noWrap>
                  {txn?.utr ? `UTR ${txn.utr}` : txn?.tid ? `TID ${txn.tid}` : "—"}
                  {txn?.createdAt ? ` · ${new Date(txn.createdAt).toLocaleDateString()}` : ""}
                </Typography>
              </Box>
              <Stack direction="row" spacing={1} alignItems="center" flexShrink={0}>
                <Typography sx={{ fontSize: compact ? 13 : 14, fontWeight: 700, color: PRIMARY, fontFamily: FONT_MONO }}>
                  ₹{txn?.amount ?? txn?.transfer_amount ?? 0}
                </Typography>
                <TxnStatusChip status={txn?.status} />
              </Stack>
            </Box>
          ))}
        </Stack>
      )}
    </Box>
  );
};

const NewBankTransfer = () => {
  const [suggestions, setSuggestions] = useState([]);
  const [error, setError] = useState("");
  const [bankPipeInfo, setBankPipeInfo] = useState({});
  const [loadingPipes, setLoadingPipes] = useState(false);

  const {
    globalLoader,
    setGlobalLoader,
    mobile,
    setMobile,
    setCurrentPage,
    currentPage,
    setCustomer,
    selectedBank,
    setSelectedBank,
    allBank,
    setAllBank,
  } = useBankTransfer();

  // Only the first 3 banks configured on the backend are ever shown —
  // names come from getBankDisplayName (preferring vendor.slug), nothing
  // hardcoded on the frontend.
  const visibleBanks = (allBank || []).slice(0, 3);
  const visibleBanksKey = useMemo(
    () => visibleBanks.map((b) => b._id).join(","),
    [visibleBanks]
  );

  const fetchSuggestions = useCallback(async () => {
    try {
      const response = await sagestMobileNumber({ mobile });
      const numbers = response?.data?.data || [];
      setSuggestions(numbers);
    } catch (err) {
      console.error("Error fetching suggestions:", err);
      setSuggestions([]);
    }
  }, [mobile]);

  useEffect(() => {
    if (!mobile) {
      setSuggestions([]);
      return;
    }

    const timeout = setTimeout(fetchSuggestions, 500);
    return () => clearTimeout(timeout);
  }, [mobile, fetchSuggestions]);

  // Dynamically inspect each bank pipe when a valid 10-digit mobile number is entered.
  // Shows real live available limits for registered banks and "New Registration" for new ones.
  useEffect(() => {
    if (!isValidIndianMobile(mobile) || visibleBanks.length === 0) {
      setBankPipeInfo({});
      setLoadingPipes(false);
      return;
    }

    let isMounted = true;
    const fetchPipeStatus = async () => {
      setLoadingPipes(true);
      try {
        const promises = visibleBanks.map(async (bank) => {
          try {
            const res = await CustomerInfo({ mobile, api_id: bank._id });
            if (!isMounted) return null;
            if (res?.data?.statusCode === "200") {
              const resp = res?.data?.data?.response;
              return {
                bankId: bank._id,
                status: "REGISTERED",
                available: resp?.available_limit ?? 25000,
                used: resp?.used_limit ?? 0,
                total: resp?.total_limit ?? 25000,
                name: resp?.name,
              };
            } else if (res?.data?.statusCode === "401") {
              return {
                bankId: bank._id,
                status: "NOT_REGISTERED",
                message: "New Registration",
              };
            }
          } catch (err) {
            // Safe fallback if network error
          }
          return {
            bankId: bank._id,
            status: "UNKNOWN",
          };
        });

        const results = await Promise.all(promises);
        if (isMounted) {
          const infoMap = {};
          results.forEach((r) => {
            if (r && r.bankId) infoMap[r.bankId] = r;
          });
          setBankPipeInfo(infoMap);
        }
      } catch (e) {
        // Safe fallback
      } finally {
        if (isMounted) setLoadingPipes(false);
      }
    };

    const timer = setTimeout(fetchPipeStatus, 300);
    return () => {
      isMounted = false;
      clearTimeout(timer);
    };
  }, [mobile, visibleBanksKey]);

  const handleInputChange = (_, newValue) => {
    const val = newValue.replace(/\D/g, "").slice(0, 10);

    setMobile(val);

    if (!val) {
      setError("");
      setBankPipeInfo({});
    } else if (val.length < 10 || !isValidIndianMobile(val)) {
      setError("Enter a valid 10-digit mobile number.");
      setBankPipeInfo({});
    } else {
      setError("");
    }
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!isValidIndianMobile(mobile)) {
      setError("Please enter a valid mobile number.");
      return;
    }
    setGlobalLoader(true);
    let body = {
      mobile: mobile,
      api_id: selectedBank,
    };
    try {
      let res = await CustomerInfo(body);
      if (res?.data?.statusCode === "401") {
        setCurrentPage("add-customer");
      }
      if (res?.data?.statusCode === "008") setCurrentPage("otp-page");

      if (res?.data?.statusCode === "007") {
        setCurrentPage("marchant-onboarding-otp");
      }
      if (res?.data?.statusCode === "200") {
        setCustomer(res?.data?.data?.response);
        setCurrentPage("send-money-page");
      }

      toastMessage(res?.data?.error, res?.data?.message);
    } catch (error) {
    } finally {
      setGlobalLoader(false);
    }
  };

  const getBank = async () => {
    let res = await settingBank();
    setAllBank(res?.data?.data?.dmtApiType || []);
    setSelectedBank(res?.data?.data?.defaultApi);
  };

  useEffect(() => {
    getBank();
  }, []);

  const handleBankChange = (id) => {
    setSelectedBank(id);
  };

  const landingStepIndex = !isValidIndianMobile(mobile) ? 0 : !selectedBank ? 1 : 2;

  return (
    <Box sx={{ position: "relative", isolation: "isolate", height: "calc(100vh - 96px)", maxHeight: "calc(100vh - 96px)", overflow: currentPage === "add-customer" ? "auto" : "hidden", backgroundColor: BG_LIGHT, borderRadius: "12px" }}>
      <Box
        component="img"
        src={banktransfer}
        alt=""
        aria-hidden="true"
        sx={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: "100%",
          width: "100%",
          objectFit: "cover",
          zIndex: -1,
          pointerEvents: "none",
        }}
      />
      <Box
        sx={{
          p: { xs: 0.75, md: 1 },
          height: "100%",
          maxHeight: "100%",
          overflow: { xs: "auto", md: currentPage === "add-customer" ? "auto" : "hidden" },
          display: "flex",
          flexDirection: "column",
          justifyContent: currentPage === "money-transfer" ? "center" : "flex-start",
          boxSizing: "border-box",
        }}
      >
        {globalLoader && <Loader />}

        <style>{`
          .dmt-autofill-input input,
          .dmt-autofill-input input:-webkit-autofill,
          .dmt-autofill-input input:-webkit-autofill:hover,
          .dmt-autofill-input input:-webkit-autofill:focus,
          .dmt-autofill-input input:-webkit-autofill:active,
          .mui-autofill-fix input,
          .mui-autofill-fix input:-webkit-autofill,
          .mui-autofill-fix input:-webkit-autofill:hover,
          .mui-autofill-fix input:-webkit-autofill:focus,
          .mui-autofill-fix input:-webkit-autofill:active,
          input.MuiOutlinedInput-input:-webkit-autofill,
          input.MuiOutlinedInput-input:-webkit-autofill:hover,
          input.MuiOutlinedInput-input:-webkit-autofill:focus,
          input.MuiOutlinedInput-input:-webkit-autofill:active {
            -webkit-text-fill-color: #101B34 !important;
            color: #101B34 !important;
            -webkit-box-shadow: 0 0 0px 1000px #ffffff inset !important;
            box-shadow: 0 0 0px 1000px #ffffff inset !important;
            caret-color: #101B34 !important;
            transition: background-color 5000s ease-in-out 0s;
          }
        `}</style>

        {currentPage === "money-transfer" && (
          <PageTransition transitionKey="landing">
            <Box sx={{ maxWidth: 760, mx: "auto", width: "100%" }}>
              <CustomBox sx={{ mb: 0, py: { xs: 1.5, md: 1.75 }, px: { xs: 2, md: 2.5 } }}>
                <Box sx={{ mb: 1.75, pb: 1.25, borderBottom: `1px solid ${LINE}` }}>
                  <Typography
                    sx={{
                      fontFamily: FONT_DISPLAY,
                      fontWeight: 600,
                      fontSize: { xs: 24, md: 28 },
                      color: NAVY_TEXT,
                      lineHeight: 1.1,
                      letterSpacing: "-0.5px",
                    }}
                  >
                    Bank Transfer
                  </Typography>
                  <Typography sx={{ fontSize: 12.5, color: MUTED, fontFamily: FONT_UI, mt: 0.5 }}>
                    Send money securely to your saved beneficiaries
                  </Typography>
                </Box>

                <FlowStepper
                  steps={["Find customer", "Choose bank", "Confirm"]}
                  activeIndex={landingStepIndex}
                />

                <Typography
                  sx={{
                    fontFamily: FONT_UI,
                    fontSize: 10.5,
                    fontWeight: 700,
                    letterSpacing: "1.4px",
                    color: GOLD,
                    mb: 0.75,
                    display: "block",
                  }}
                >
                  01 &nbsp;·&nbsp; FIND CUSTOMER
                </Typography>

                <Typography sx={{ fontFamily: FONT_DISPLAY, fontSize: 16, fontWeight: 600, color: NAVY_TEXT, mb: 0.25 }}>
                  Look up by mobile number
                </Typography>
                <Typography sx={{ fontSize: 12, color: MUTED, fontFamily: FONT_UI, mb: 1.5 }}>
                  Enter the customer's registered 10-digit mobile number to continue.
                </Typography>

                <Box
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 1.5,
                    borderBottom: `2px solid ${error ? DANGER : LINE}`,
                    pb: 0.5,
                    "&:focus-within": { borderBottomColor: GOLD },
                    transition: "border-color 0.15s ease",
                  }}
                >
                  <Typography
                    sx={{
                      fontFamily: FONT_MONO,
                      fontSize: { xs: 20, md: 24 },
                      color: GOLD,
                      lineHeight: 1,
                      display: "flex",
                      alignItems: "center",
                    }}
                  >
                    +91
                  </Typography>
                  <Autocomplete
                    freeSolo
                    options={suggestions}
                    getOptionLabel={(option) =>
                      typeof option === "string" ? option : option.customer_number
                    }
                    inputValue={mobile}
                    onInputChange={handleInputChange}
                    fullWidth
                    sx={{ flex: 1 }}
                    renderInput={(params) => (
                      <Box ref={params.InputProps.ref} sx={{ width: "100%" }}>
                        <input
                          {...params.inputProps}
                          placeholder="98765 43210"
                          autoFocus
                          style={{
                            width: "100%",
                            border: "none",
                            outline: "none",
                            background: "transparent",
                            fontFamily: "'IBM Plex Mono', monospace",
                            fontSize: "clamp(18px, 3vw, 24px)",
                            lineHeight: 1,
                            color: NAVY_TEXT,
                            letterSpacing: "1px",
                            padding: 0,
                            margin: 0,
                            display: "block",
                          }}
                        />
                      </Box>
                    )}
                  />
                </Box>

                {error ? (
                  <Typography variant="caption" sx={{ display: "block", color: DANGER, mt: 0.75, fontFamily: FONT_UI }}>
                    {error}
                  </Typography>
                ) : mobile?.length > 0 && mobile.length !== 10 ? (
                  <Typography variant="caption" sx={{ display: "block", color: MUTED, mt: 0.75, fontFamily: FONT_UI }}>
                    {10 - mobile.length} digit{10 - mobile.length !== 1 ? "s" : ""} remaining
                  </Typography>
                ) : null}

                <Collapse in={isValidIndianMobile(mobile)} timeout={350} unmountOnExit>
                  <Box sx={{ mt: 2, pt: 1.5, borderTop: `1px dashed ${LINE}` }}>
                    <Typography
                      sx={{
                        fontFamily: FONT_UI,
                        fontSize: 10.5,
                        fontWeight: 700,
                        letterSpacing: "1.4px",
                        color: GOLD,
                        mb: 0.5,
                        display: "block",
                      }}
                    >
                      02 &nbsp;·&nbsp; TRANSFER THROUGH
                    </Typography>

                    <Typography sx={{ fontSize: 12, color: MUTED, fontFamily: FONT_UI, mb: 1.25 }}>
                      Choose which bank to route this transfer through.
                    </Typography>

                    <Box
                      sx={{
                        display: "grid",
                        gridTemplateColumns: {
                          xs: "1fr",
                          sm: `repeat(${Math.min(visibleBanks.length, 3)}, 1fr)`,
                        },
                        gap: 1.25,
                        mb: 1.5,
                      }}
                    >
                      {visibleBanks.map((bank) => {
                        const isSelected = selectedBank === bank._id;
                        const pipeInfo = bankPipeInfo[bank._id];
                        const isRegistered = pipeInfo?.status === "REGISTERED";
                        const isNotRegistered = pipeInfo?.status === "NOT_REGISTERED";

                        return (
                          <Box
                            key={bank._id}
                            onClick={() => handleBankChange(bank._id)}
                            sx={{
                              position: "relative",
                              display: "flex",
                              alignItems: "center",
                              justifyContent: "space-between",
                              gap: 1,
                              p: "8px 12px",
                              borderRadius: "10px",
                              cursor: "pointer",
                              border: `1.5px solid ${isSelected ? GOLD : LINE}`,
                              backgroundColor: isSelected ? "rgba(185,138,70,0.06)" : "#FFFFFF",
                              transition: "all 0.18s ease",
                              "&:hover": {
                                borderColor: GOLD,
                                backgroundColor: "rgba(185,138,70,0.04)",
                              },
                            }}
                          >
                            <Box sx={{ display: "flex", alignItems: "center", gap: 1, minWidth: 0 }}>
                              <AccountBalanceIcon sx={{ fontSize: 17, color: isSelected ? GOLD : MUTED, flexShrink: 0 }} />
                              <Box sx={{ minWidth: 0 }}>
                                <Typography
                                  noWrap
                                  sx={{
                                    fontFamily: FONT_DISPLAY,
                                    fontSize: 13,
                                    fontWeight: isSelected ? 700 : 500,
                                    color: isSelected ? NAVY_TEXT : MUTED,
                                  }}
                                >
                                  {getBankDisplayName(bank)?.toUpperCase()}
                                </Typography>
                                {loadingPipes && !pipeInfo ? (
                                  <Box sx={{ display: "flex", alignItems: "center", gap: 0.5, mt: 0.2 }}>
                                    <CircularProgress size={8} sx={{ color: GOLD }} />
                                    <Typography
                                      variant="caption"
                                      sx={{
                                        display: "block",
                                        fontSize: 9.5,
                                        color: MUTED,
                                        fontWeight: 500,
                                        lineHeight: 1.1,
                                      }}
                                    >
                                      Checking...
                                    </Typography>
                                  </Box>
                                ) : isRegistered ? (
                                  <Typography
                                    variant="caption"
                                    sx={{
                                      display: "block",
                                      fontSize: 10,
                                      color: "#107E5A",
                                      fontWeight: 700,
                                      lineHeight: 1.1,
                                      mt: 0.2,
                                    }}
                                  >
                                    Available: ₹{Number(pipeInfo.available).toLocaleString("en-IN")}
                                  </Typography>
                                ) : isNotRegistered ? (
                                  <Typography
                                    variant="caption"
                                    sx={{
                                      display: "inline-block",
                                      fontSize: 9.5,
                                      color: "#D97706",
                                      fontWeight: 600,
                                      lineHeight: 1.1,
                                      mt: 0.2,
                                      backgroundColor: "rgba(217,119,6,0.08)",
                                      px: 0.6,
                                      py: 0.15,
                                      borderRadius: "4px",
                                    }}
                                  >
                                    ✦ New Registration
                                  </Typography>
                                ) : (
                                  <Typography
                                    variant="caption"
                                    sx={{
                                      display: "block",
                                      fontSize: 10,
                                      color: isSelected ? PRIMARY : MUTED,
                                      fontWeight: 500,
                                      lineHeight: 1.1,
                                      mt: 0.2,
                                    }}
                                  >
                                    Limit: Up to ₹25,000
                                  </Typography>
                                )}
                              </Box>
                            </Box>
                            {isSelected ? (
                              <CheckCircle sx={{ fontSize: 16, color: GOLD, flexShrink: 0 }} />
                            ) : (
                              <Box
                                sx={{
                                  width: 14,
                                  height: 14,
                                  borderRadius: "50%",
                                  border: `1.5px solid ${LINE}`,
                                  flexShrink: 0,
                                }}
                              />
                            )}
                          </Box>
                        );
                      })}
                    </Box>

                    <Box
                      sx={{
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "space-between",
                        mt: 1.5,
                        flexWrap: "wrap",
                        gap: 1,
                      }}
                    >
                      {selectedBank ? (
                        (() => {
                          const activePipeInfo = bankPipeInfo[selectedBank];
                          const isReg = activePipeInfo?.status === "REGISTERED";
                          const isNotReg = activePipeInfo?.status === "NOT_REGISTERED";

                          return (
                            <Stack direction="row" spacing={0.75} alignItems="center">
                              <CheckCircle sx={{ fontSize: 14, color: isNotReg ? "#D97706" : PRIMARY }} />
                              <Typography sx={{ fontSize: 11.5, color: MUTED, fontFamily: FONT_UI }}>
                                Routing through{" "}
                                <Box component="span" sx={{ color: NAVY_TEXT, fontWeight: 700 }}>
                                  {getBankDisplayName(visibleBanks.find((b) => b._id === selectedBank))?.toUpperCase()}
                                </Box>
                                {isReg && (
                                  <Box component="span" sx={{ color: "#107E5A", fontWeight: 700, ml: 0.75 }}>
                                    (₹{Number(activePipeInfo.available).toLocaleString("en-IN")} available)
                                  </Box>
                                )}
                                {isNotReg && (
                                  <Box component="span" sx={{ color: "#D97706", fontWeight: 600, ml: 0.75 }}>
                                    (Registration required)
                                  </Box>
                                )}
                              </Typography>
                            </Stack>
                          );
                        })()
                      ) : (
                        <span />
                      )}
                      <Button
                        variant="contained"
                        disabled={!isValidIndianMobile(mobile) || !selectedBank}
                        onClick={handleSearch}
                        sx={{ px: 3.5, height: 38, fontSize: "13px", ...gradientBtnSx(!isValidIndianMobile(mobile) || !selectedBank) }}
                      >
                        {bankPipeInfo[selectedBank]?.status === "NOT_REGISTERED" ? "Register Remitter" : "Search"}
                      </Button>
                    </Box>
                  </Box>
                </Collapse>

                <Box sx={{ display: "flex", alignItems: "center", gap: 1, mt: 2, opacity: 0.8 }}>
                  <LockIcon sx={{ fontSize: 13, color: GOLD }} />
                  <Typography sx={{ fontSize: 11, color: MUTED, fontFamily: FONT_UI }}>
                    Encrypted end-to-end · RBI-compliant DMT rails
                  </Typography>
                </Box>
              </CustomBox>
            </Box>
          </PageTransition>
        )}

        {currentPage === "send-money-page" && (
          <PageTransition
            transitionKey="send-money-page"
            style={{ height: "100%", width: "100%" }}
            sx={{
              height: "100%",
              width: "100%",
              display: "flex",
              flexDirection: "column",
              overflow: { xs: "auto", md: "hidden" },
            }}
          >
            <BankTransferMoneyTransferPage />
          </PageTransition>
        )}
        {currentPage === "add-newBeneficiaryPage" && (
          <PageTransition transitionKey="add-newBeneficiaryPage"><AddNewBeneficiaryPage /></PageTransition>
        )}
        {currentPage === "add-customer" && (
          <PageTransition transitionKey="add-customer"><AddCustomer /></PageTransition>
        )}
        {currentPage === "otp-page" && <OtpPopUp />}
        {currentPage === "marchant-onboarding-otp" && <MarchantOnboarding />}
        {currentPage === "KYC-page" && (
          <PageTransition transitionKey="KYC-page"><KYCPage /></PageTransition>
        )}
        {currentPage === "invoice" && (
          <PageTransition transitionKey="invoice"><InvoiceRecord /></PageTransition>
        )}
      </Box>
    </Box>
  );
};

export default NewBankTransfer;